using System.Security.Claims; using MaintenancePRO.Api.Contracts; using MaintenancePRO.Api.Data; using MaintenancePRO.Api.Models; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore;
namespace MaintenancePRO.Api.Controllers;
[ApiController,Route("api/diagnoses"),Authorize(Policy="ManageMaintenance")]
public sealed class DiagnosesController(AppDbContext db):ControllerBase {
 [HttpGet] public async Task<IActionResult> List([FromQuery]int? breakdownId)=>Ok(await db.Diagnoses.AsNoTracking().Where(x=>breakdownId==null||x.BreakdownId==breakdownId).OrderByDescending(x=>x.CreatedUtc).ToListAsync());
 [HttpPost] public async Task<IActionResult> Create([FromQuery]int breakdownId,CreateDiagnosisRequest r){var b=await db.Breakdowns.FindAsync(breakdownId);if(b==null)return NotFound(new{message="Panne introuvable."});if(b.Status is BreakdownStatus.Resolved or BreakdownStatus.Closed or BreakdownStatus.Rejected)return Conflict(new{message="Impossible de diagnostiquer une panne clôturée."});var x=new Diagnosis{BreakdownId=breakdownId,Findings=r.Findings.Trim(),RootCause=r.RootCause?.Trim(),RecommendedAction=r.RecommendedAction?.Trim(),CreatedByUserId=User.FindFirstValue(ClaimTypes.NameIdentifier)!};db.Diagnoses.Add(x);b.Status=BreakdownStatus.Diagnosing;db.AuditEvents.Add(new AuditEvent{ActorUserId=x.CreatedByUserId,Action="DiagnosisCreated",EntityType="Diagnosis",EntityId=x.Id.ToString()});await db.SaveChangesAsync();return CreatedAtAction(nameof(Get),new{id=x.Id},x);}
 [HttpGet("{id:int}")] public async Task<IActionResult> Get(int id){var x=await db.Diagnoses.AsNoTracking().FirstOrDefaultAsync(x=>x.Id==id);return x==null?NotFound():Ok(x);}
 [HttpPatch("{id:int}/decision"),Authorize(Policy="ManageEquipment")] public async Task<IActionResult> Decision(int id,DiagnosisDecisionRequest r){if(r.Status is not (DiagnosisStatus.Approved or DiagnosisStatus.Rejected))return BadRequest(new{message="Décision attendue: Approved ou Rejected."});var x=await db.Diagnoses.Include(x=>x.Breakdown).FirstOrDefaultAsync(x=>x.Id==id);if(x==null)return NotFound();x.Status=r.Status;if(x.Breakdown!=null)x.Breakdown.Status=r.Status==DiagnosisStatus.Approved?BreakdownStatus.InMaintenance:BreakdownStatus.AwaitingApproval;db.AuditEvents.Add(new AuditEvent{ActorUserId=User.FindFirstValue(ClaimTypes.NameIdentifier),Action="DiagnosisDecision",EntityType="Diagnosis",EntityId=id.ToString()});await db.SaveChangesAsync();return Ok(x);}
}
